-- Halaman informasi publik (info KIAS) + Visi & Misi yang bisa disunting admin.
--
-- 1. Tabel `halaman_info`: satu baris = satu halaman informasi (slug dipakai di URL).
-- 2. Kolom `profil.visi` & `profil.misi`: HTML untuk section Visi & Misi di beranda
--    dan halaman /visi-misi.
-- 3. Seed: 6 halaman info KIAS (isi diambil dari Google Form "INFO KURSUS ILMU ARAB
--    DAN SYAR'I (KIAS)") + isi Visi & Misi awal (sama dengan teks yang sebelumnya
--    tertanam di komponen beranda).
--
-- Seed konten di bawah HANYA titik awal: seluruh isi bisa disunting ulang dari
-- panel admin (/admin/info dan /admin/profil) memakai editor WYSIWYG.

CREATE TABLE `halaman_info` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `slug` VARCHAR(191) NOT NULL,
  `judul` VARCHAR(191) NOT NULL,
  `kategori` VARCHAR(50) NOT NULL DEFAULT 'KIAS',
  `ringkasan` VARCHAR(500) NULL,
  `konten` LONGTEXT NOT NULL,
  `urutan` INT NOT NULL DEFAULT 0,
  `tampil` TINYINT(1) NOT NULL DEFAULT 1,
  `updated_by_id` INT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `halaman_info_slug_key` (`slug`),
  KEY `halaman_info_kategori_urutan_idx` (`kategori`, `urutan`),
  CONSTRAINT `halaman_info_updated_by_id_fkey` FOREIGN KEY (`updated_by_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

ALTER TABLE `profil`
  ADD COLUMN `visi` LONGTEXT NULL,
  ADD COLUMN `misi` LONGTEXT NULL;

UPDATE `profil` SET `visi` = '<p>Menjadi Program Studi Hukum Keluarga Islam unggulan dalam melahirkan generasi ulama rabbani yang profesional, sarjana hukum yang mutqin, kokoh dalam manhaj, serta adaptif terhadap dinamika keberagamaan.</p>', `misi` = '<ol><li>Menyelenggarakan pendidikan dan pengajaran unggul dalam bidang Hukum Keluarga Islam.</li><li>Mengembangkan penelitian dan kajian ilmiah yang responsif terhadap kebutuhan masyarakat.</li><li>Melaksanakan pengabdian kepada masyarakat berbasis pendidikan dan penelitian.</li><li>Membangun kemitraan dan jaringan kerjasama strategis.</li></ol>' WHERE `id` = 1;

INSERT INTO `halaman_info` (`slug`, `judul`, `kategori`, `ringkasan`, `konten`, `urutan`, `tampil`) VALUES
('profil-kias', 'Profil KIAS', 'KIAS', 'Profil KIAS: muqodimah, visi dan misi, kompetensi lulusan, muqorroor kitab, peserta, serta program waktu dan tempat belajar.', '<b>1. MUQODIMAH</b><br />Segala puji bagi Allah yang telah mengajar manusia dengan perantaraan pena, mengajari manusia apa yang tidak diketahuinya. <br />Sesungguhnya menuntut ilmu merupakan ibadah dan pendekatan diri yang paling agung dari seorang hamba kepada Rabbnya. Merupakan ketaatan yang paling nyata sehingga dengan ilmu itulah kedudukan dan kapasitas seorang muslim menjadi  tinggi di sisi Allah. Allah telah memerintahkan hamba-Nya untuk berilmu, mempelajari dan mengamalkannya dengan penuh keikhlasan mencari Ridho-Nya serta senantiasa ittiba/meneladani Rasulullah dalam mengaplikasikan ilmu tersebut dalam kehidupan sehari-hari. <br /><br /><b>2. VISI DAN MISI</b><br /><b>Visi :</b><br />Menjadi lembaga pendidikan yang berkualitas serta mampu mengembangkan dan menghasilkan generasi muslim sesuai manhaj salafush shalih.<br /><b>Misi:</b><br />Misi lembaga adalah membangun dan menyelenggarakan sistem pendidikan komprehensif yang mampu menyiapkan lulusannya untuk menjadi generasi muslim sesuai manhaj salafush shalih.<br /><br /><b>3. OPERASIONAL MISI</b>Menyelenggarakan Program Pendidikan<br />01) Tajwid Al-Quran <br />02) Bahasa Arab Reguler &amp; Takmili<br /><br /><b>4.TUJUAN</b>	<br />Setelah mengikuti proses pendidikan dengan benar maka peserta diharapkan memiliki kompetensi:<br />01) Mengenal nilai-nilai Islam serta mampu mempraktikannya dalam kehidupan<br />02) Mamiliki dasar-dasar Ilmu Tajwid <br />03) Memiliki dasar-dasar Bahasa Arab<br />04) Mampu membaca kitab para ulama yang berbahasa Arab<br />05) Memiliki akhlak yang mulia.<br /><br /><b>5. PENGURUS</b><b>SUSUNAN PENGURUS</b><b>MA’HAD ALY IMAM SYATHIBY</b><b>PERIODE 2025-2027</b><b>Mudir: </b>Ustadz Dr. Muhamad Yasir, M.A.<b><br /></b><b>Kabag Pengembangan Kurikulum</b><br /><b>Ketua:</b> Ustadz Zahirman Edri<b><br /></b><b>Anggota:</b><br />1. Ustadz Irham Maulana, B.A., M.H.<b><br /></b>2. Ustadz Dr. Cecep Rahmat, Lc. M.Ag.<b><br /></b>3. Ustadz Cecep Nurohman, B.A., M.A.<br />4. Ustadz Derma Permana, B.A.<br /><b>Kepegawaian:</b><br />Ustadz Mukhadasin, M.Pd.<b><br /></b><b>Kesekretariatan:</b><br />1. Bapak Drs. Muliadi<b><br /></b>2. Bapak Yudi Jamaludin, S.Pd.<br /><b>Keuangan:</b><br />1. Akh. Agung, S.T.<b><br /></b>2. Windi Zulfianto Askot<br /><b>ROIS QISM</b><br /><b>Tajwid Al-Quran</b>	<br />Ustadz Rifki<br /><b>Bahasa  Arab </b>Reguler/ TakmiliUstadz Zahirman Edri<br /><br /><b>6. KURIKULUM</b><br />Mengimplementasikan kurikulum dengan menekankan kekhasan, yaitu:<br />01) Merupakan kurikulum yang telah dikembangkan <br />02) Mempertimbangkan usia dan kemampuan peserta<br />03) Kurikulum ini merupakan hasil studi Tim Pengembang KIAS<br /><b>7. METODE</b><br />Metode pembelajaran yang diterapkan adalah sbb.: <br /><b>01) Terpadu dan Tematik; </b>segala hal yang dipelajari saling terkait<b>02) Terintegrasi dan Kontekstual;</b> segala hal yang dipelajari saling terkait dan dekat dengan kehidupan sehari-hari<b>03) Kreatif dan Inovatif; </b>melalui kegiatan yang menarik yang dapat membangkitkan rasa ingin tahu, memotivasi  untuk berpikir dan menemukan hal-hal baru.<b>04) Inquiry; </b>memelihara keingintahuan melalui keteram-pilan proses yang eksploratif dengan belajar melalui praktek di lapangan dimana lingkungan alam dan sekitar menjadi sumber belajar.<b>05) Konstruktivisme;</b> belajar dari apa yang telah diketahui oleh santri secara bertahap dari yang sederhana ke kompleks.<b>06) Santri Active Learning (SAL);</b> belajar aktif atau belajar yang berpusat pada santri sesuai dengan kebutuhan perkembangan santri dalam segala aspek.<b>07) Santri dihargai </b>kemampuannya dan diberi kesempatan untuk mengembangkan potensinya.<br /><br /><b>8. BIAYA PENDIDIKAN</b><br />Biaya pendidikan adalah biaya yang dikenakan kepada Santri/Mahasiswa untuk penyelenggaraan dan pembinaan pendidikan serta layanan administrasi akademik. Rincian biaya <br /><b>01) Pendaftaran	Rp 150.000,-	</b><br />Pendaftaran, Tes dan Penempatan<b>02) Sarpras Maintenance Rp 300.000,-</b><br />Pendaftaran, Tes dan Penempatan<br /><b>03) Syahriyyah Rp 250.000,-</b> <br />Perkuliahan, UTS, UAS, Transkrip UAS<br /><b>04) Daftar Ulang/Mutasi	Rp 100.000,-</b>	<br />Daftar Ulang/Mutasi, dan penempatan<br /><b>05) Transkrip dan Ijazah Kelulusan</b>	<br />Rp 100.000,- Cetak Transkrip dan Ijazah<br /><b>06) Biaya Kitab</b>	<br />Menyesuaikan Materi Perkuliahan<br /><br /><b>9. MENGAPA MEMILIH KIAS</b><br />Mengapa memilih KIAS? Karena lembaga ini berbeda dengan lembaga pendidikan yang telah ada; karena memiliki keunikan yaitu lembaga ini mengembangkan kurikulum yang berpusat pada potensi, perkembangan dan kepentingan para santri dan lingkungannya; beragam dan terpadu, relevan dengan kebutuhan kehidupan; menyeluruh dan berkesinambungan serta belajar sepanjang hayat.<br />In Syaa Allah para santri akan mendapatkan pendidikan yang bermutu, dinamis dan menyenangkan; bersifat tashfiyah dan tarbiyah; suasana yang saling menerima, menghargai akrab sesuai sunnah; seimbang terkait dan berkesinambungan antar jenjang pendidikan.<br />Kesimpulannya adalah marilah mempelajari ilmu syari dengan bergabung bersama KIAS<br /><br /><b>10. FASILITAS </b><br />Ma’had Syathiby terdiri dari: Ruang kelas, Gedung administrasi, Lapangan parkir motor/mobil, dan sarana prasarana belajar.<br />Mesjid Al-Barkah; dipergunakan untuk shalat berjama’ah. <br />Perpustakaan Syathiby: dapat dijadikan referensi pembelajaran dan pendalaman ilmu, terdiri dari kitab-kitab berbahasa arab dan berbahasa Indonesia.Gedung Administrasi; untuk pembayaran Syahriyyah, pengambila kartu UAS, Transkrip/Ijazah <br />Lapangan Parkir; di halaman depan Ma''had Syathiby dipergunakan untuk parkir mobil dan motor.Sarana Belajar yang dipergunakan yaitu kamera, proyektor dll.<br /><br />------------------------------------------<br /><br />', 1, 1),
('profil-tajwid', 'Profil Tajwid Al-Qur''an', 'KIAS', 'Profil program Tajwid Al-Qur''an KIAS: muqodimah, standar kompetensi lulusan, kitab panduan, peserta, dan jadwal belajar.', '<b>1. MUQODIMAH</b><br />Allah Subhanahu wa Ta’ala berfirman: “Orang-orang yang telah Kami beri Kitab, mereka membacanya sebagaimana mestinya, mereka itulah orang yang beriman kepadanya..” (QS al-Baqarah: 121)<br />“Sebaik-baik kalian adalah yang belajar Al-Quran dan yang mengajarkannya.” (HR. al-Bukhori, dari Utsman bin Affan)<br />“Orang yang mahir membaca (dan menghafal) al-Quran bersama para malaikat yang mulia lagi taat (pada hari kiamat). Orang yang membaca al-Quran dengan terbata-bata lagi sulit (dalam membacanya) mendapatkan 2 pahala.” (HR. Muslim)<br />Membaca al-Quran tidak seperti membaca kitab-kitab lain buatan manusia. Membaca al-Quran harus sesuai dengan yang diperintahkan Allah dan dicontohkan oleh Rasul-Nya.<br />Allah berfirman: “… dan bacalah al-Quran itu dengan perlahan-lahan.” (QS.al-Muzamil:4)<br />Al-Imam Ibnul Jajari rohimahulahu mengatakan:<br />“Membaca al-Quran dengan tajwid hukumnya wajib barang siapa yang membacanya tidak dengan tajwid ia berdosa karena dengan tajwidlah Allah menurunkan al-Quran dan demikian pula al-Quran sampai kepada kita.”<br />Berdasarkan dalil di atas, kaum muslimin diwajibkan membaca al-Quran dengan tajwid. Maka ilmu tajwid merupakan ilmu yang sangat penting dipelajari oleh kaum muslimin dan cara terbaik yaitu dengan berguru kepada seorang yang ahli, sebagaimana Rasulullah shalalllahu alaihi wa salam pun langsung diajarkan oleh malaikat Jibril alaihi salam.<br /><br /><b>2. STANDAR KOMPETENSI LULUSAN</b><br />Setelah menyelesaikan pendidikan Tajwid Al-Quran selama 1 tahun diharapkan para peserta memiliki kemampuan membaca dan menulis Al Quran dengan baik dan benar.<br />Setelah mengikuti proses pendidikan dengan baik dan benar maka para santri diharapkan memiliki kompetensi:<br />1) Mampu membaca dan menulis Al-Quran dengan baik dan benar<br />2) Memiliki dasar-dasar Ilmu Tajwid<br />3) Mengenal nilai-nilai Islam serta mampu mempraktekannya dalam kehidupan<br />4) Memiliki akhlak yang mulia<br /><b>3. MUQOROR KITAB PANDUAN</b><b>PROGRAM TAJWID</b>1) <b>Teori Tajwid; </b>Metode As-Syafi''i (Ust. Kurnaedi, Lc.)2) <b>Bahasa Arab; </b>Qiroah wal Kitabah Silsilah Jilid 1 (Jami''ah Muhammad Bin Su''ud KSA)<br /><b>4. PESERTA</b><br />Santri Tajwid Al-Quran adalah: <br />1) Ikhwan dan Akhwat yang belum bisa baca dan tulis Al-Quran. <br />2) Ikhwan dan Akhwat yang sudah bisa baca tulis Al-Quran namun ingin mempelajar ilmu Tajwid.<br /><b>5. PROGRAM WAKTU DAN TEMPAT</b><b>01) AL-BARKAH TAJWID AL-QURAN</b>	<br />Paket 1 Tahun	<br />Hari Sabtu	<br />Pukul 07.30-11.45	<br />Tempat Ma''had Syathiby Cileungsi<br /><br />', 2, 1),
('profil-bahasa-arab-takmili', 'Profil Bahasa Arab & Takmili', 'KIAS', 'Profil program Bahasa Arab Reguler dan Takmili KIAS: muqodimah, kompetensi, muqorroor kitab, peserta, dan jadwal belajar.', '<b>1. MUQODIMAH</b><br />“Bahasa Arab adalah bahasa yang paling fasih dan paling jelas, paling luas dan paling banyak dalam penyampaian makna-maknanya, serta bisa menenangkan jiwa. Oleh karena itu diturunkan kitab yang paling mulia (al-Quran) menggunakan bahasa yang mulia(bahasa Arab).” (Ibnu Katsir, Tafsir al-Quran al-Azhim, 2/511)<br />Allah Subhanahu wa Ta’ala menurunkan al-Quran dengan bahasa Arab dan mengutus utusan-Nya, Nabi Muhammad Shalallahu ‘alaihi wa sallam’ dengan bahasa Arab. Para ulama pembela Sunnah menerangkan al-Quran dan al-Hadits juga dengan bahasa Arab.<br />Dengan demikian, mempelajari bahasa Arab merupakan bagian dari din (agama). Hukum mempelajarinya wajib bagi umat Islam yang mampu dan bertanggung jawab atas tersebarnya Islam dipermukaan bumi ini. Tidak mungkin untuk memahami dinul-Islam dengan pemahaman yang benar, kecuali dengan bahasa Arab.<br /><br /><b>2. STANDAR KOMPETENSI LULUSAN</b><br />Santri menguasai 4 keterampilan bahasa (mendengar, membaca, berbicara dan menulis) sesuai dengan batas kurikulum yang berlaku dengan menekankan pada kemampuan membaca dan mendengar serta dibekali dengan pengetahuan Aqidah, Manhaj dan Fiqih, dengan harapan santri mampu mengikuti  jenjang berikutnya yaitu program takhasssus  ilmu syar’i dengan baik.<br /><b>3. MUQORROR KITAB PANDUAN</b><br /><b>PROGRAM BAHASA ARAB </b><b>REGULER 1</b>1) <b>Pengantar: </b>Muqodimah Mukhtarot (Ust. Zahir Al-Minangkabawi)2) <b>Pengantar; </b>Auzan Mukhtarot (Ust. Zahir Al-Minangkabawi)3) <b>Nahwu; </b>Mukhtarot Qowaid Al-Lughah Al-Arabiyah (Ust. Aunur Rofiq bin Gufron, Lc.)4) <b>Nahwu; </b>Tadribat Mukhtarat Durusul Lughah 1 (Ust. Abu Izza Irham Maulana, Lc.)5) <b>Tarakib; </b>Durusul Lughah Jilid 1 (Syaikh Dr. V. Abdurrahim)6) <b>Sharaf; </b>Al-Lamhah Fi Tashrif wa Qowaidihi (Ust. Zahir Al-Minangkabawi)7) <b>Aqidah; </b>Al-Arbai''in Fi Huquq Rabb Al-A''lamin (Anis bin Nashir Al-Mush''abi)8) <b>Adab &amp; Motivasi; </b>Khulashah Ta''zhim Al-Ilm (Syaikh Dr. Shalih bin Abdullah Al-Ushaimi)<b>-------------------------------------</b><br /><b>PROGRAM BAHASA ARAB </b><b>REGULER 2</b>1) <b>Nahwu; </b>Mukhtarot Qowaid Al-Lughah Al-Arabiyah (Ust. Aunur Rofiq bin Gufron, Lc.)<br />2) <b>Nahwu; </b>Tadribat Mukhtarat Durusul Lughah (Ust. Abu Izza Irham Maulana, Lc.)3) <b>Tarakib; </b>Durusul Lughah Jilid 2 (Syaikh Dr. V. Abdurrahim)4) <b>Sharaf; </b>Al-Lamhah Fi Tashrif wa Qowaidihi (Ust. Zahir Al-Minagkabawi)5) <b>Hadits; </b>Al-Arbai''in Fi Huquq Rabb Al-A''lamin (Anis bin Nashir Al-Mush''abi)<br />6) <b>Adab &amp; Motivasi; </b>Khulashah Ta''zhim Al-Ilm (Syaikh Dr. Shalih bin Abdullah Al-Ushaimi)<b>-------------------------------------</b><b><br /></b><b>PROGRAM BAHASA ARAB TAKMILI</b>1) <b>Balaghah; </b>Al-Balghah Al-Yasirah (Dr. Muhammad Yasir, Lc. MA.)2) <b>Tadrib Qira''ah;</b>Tadrib Al-Qiroah (Ust. Zahir Al-Minangkabawi)3) <b>Tarakib; </b>Durusul Lughah Jilid 3 (Syaikh Dr. V. Abdurrahim)4) <b>Aqidah;</b> Madkhal Ila Dirasah Ilmi Al-Aqidah (Dr. Khalid bin Muhammad Al-Juhani)<br />5) <b>Hadits;</b> Al-Arbai''in Fi Huquq Rabb Al-A''lamin (Anis bin Nashir Al-Mush''abi)<br />6) <b>Muthala''ah; </b>Tadribat Jilid 2 dan 3 (Ust. Abu Izza Irham Maulana, Lc.)7) <b>Adab &amp; Motivasi; </b>Khulashah Ta''zhim Al-Ilm (Syaikh Dr. Shalih bin Abdullah Al-Ushaimi)<br /><b>4. PESERTA</b><br />Peserta Bahasa Arab adalah ikhwan dan akhwat yang mampu  membaca Al-Qur’an dengan lancar atau lulusan Program Takhassus Tajwid Al-Qur’an.<br /><br /><b>5. PROGRAM WAKTU DAN TEMPAT<br />01) BA AL-BARKAH REGULER	</b><br /><b>Paket 2 Tahun</b>	<br />Hari Sabtu	<br /><b>Pukul 07.30-11.45	</b><br />Tempat Ma''had Syathiby Cileungsi<br /><br /><b>02) BA AL-BARKAH TAKMILI<br />Paket 1 Tahun</b>Hari Sabtu	<b><br />Pukul 07.30-11.45</b><br />Tempat Ma''had Syathiby Cileungsi<br /><br />', 3, 1),
('panduan-santri', 'Panduan Santri', 'KIAS', 'Panduan Santri KIAS: administrasi, kehadiran, jam belajar, ujian, daftar ulang, cuti/berhenti, syahriyyah, dan ijazah.', '<b>1. PENDAHULUAN</b><br />Maha suci Allah yang telah menciptakan alam semesta dengan teratur.<br /><br /><b>2. TUJUAN</b><br />Panduan ini dibuat dengan tujuan memudahkan santri dalam mengikuti pembelajaran di LPTA.<br /><br /><b>3. PROGRAM KIAS</b><br />Program Pendidikan Tajwid al-Quran<br />1) Al-Barkah Tajwid al-Quran<br />Program Pendidikan Bahasa Arab <br />1) Al-Barkah BA Reguler<br />2) Al-Barkah BA Takmili<br /><b>4. TEMPAT BELAJAR DAN ALAMAT</b><br />Ma’had Syathiby<br />Jl Pahlawan Kampung Tengah Komplek Mesjid Al-Barkah &amp; Radio Rodja 756am Cileungsi Kab. Bogor 16820 <br />Telp. 0811-1516-756<br /><br /><b>5. PESERTA</b><br />Peserta LPTA adalah mereka yang telah dinyatakan lulus sebagai peserta dan telah memenuhi persyaratan administrasi.<br /><br /><b>6. KEGIATAN BELAJAR</b><br />Selama KBM peserta mengikuti perkuliahan dengan sungguh-sungguh dan mengerjakan tugas-tugas di luar KBM dengan penuh tanggung jawab.<br /><br /><b>7. PENAMPILAN</b><br />Peserta berpenampilan sopan dan sesuai ketentuan syariat (dalam berpakaian dan bertutur kata).<br /><br /><b>8. KEHADIRAN</b><br />Peserta diwajibkan mengikuti perkuliahan tatap muka minimal 60%  kehadiran. <br />Peserta dapat menginformasikan izin tidak mengikuti perkuliahan via wa/telepon ke admin takhassus.<br /><br /><b>9. JAM BELAJAR</b><br />Santri dan ustadz hadir sebelum jam pelajaran dimulai.<br /><br /><b>10. ULANGAN</b><br />Peserta diwajibkan mengikuti ulangan harian (termasuk tugas-tugas), ulangan tengah semester, dan ulangan akhir semester. Hasil ulangan dalam  dituangkan dalam bentuk transkrip nilai.<br /><br /><b>11. SURAT KETERANGAN SANTRI</b><br />Peserta yang membutuhkan surat keterangan santri, dipersilakan mengisi link surat keterangan santri, lalu konfirmasi ke kontak admin untuk segera dibuatkan suratnya<br /><br /><b>12. DAFTAR ULANG</b>Semua santri mengisi Link form daftar ulang, baik naik kelas atau mengulang program; dari kelas 1 ke kelas 2, TQ ke BA, dari BA ke Takmili, dari Takmili ke Syari’ah, dikenakan biaya sebesar Rp 100.000,-. Hubungi Admin Takhassus untuk mendapatkan linknya. lalu konfirmasi ke kontak admin untuk didata.<br /><br /><b>13. CUTI/BERHENTI</b><br />Peserta yang hendak cuti/ berhenti mengikuti perkuliahan mengisi form cuti/berhenti.<br />Form Cuti berhenti diisi dengan menggunakan link Cuti/Berhenti. lalu konfirmasi ke kontak admin untuk didata.<br /><br /><b>14. SYAHRIYYAH DAN UANG KITAB</b><b>Syahriyyah adalah biaya pendidikan perpaket belajar; jadi jika dalam tahun paket belajar itu ada libur Ramadhan, maka syahriyyah tetap dibayar oleh peserta.<br />Pembayaran Syahriyah (@Rp 250.000,-) selambat-lambatnya pekan ke-2 setiap bulannya</b>*(Jika pembayaran syahriyyahnya via Transfer, maka wajib menunjukkan/mengirimkan copi bukti Transfernya ke Admin Windy Askot dan menunjukkan kartu syahriyyahnya untuk distempel/divalidasi, sebagai bukti sudah bayar syahriyyah).<br />Uang Kitab dibayarkan ketika mendapatkan kitab di Idaaroh.<br />Rincian dan besarnya syahriyah dan uang kitab ada di info KIAS bagian biaya pendidikan.<br /><br /><b>15.	PENILAIAN DAN TRANSKRIP NILAI</b><br />Seluruh peserta mendapatkan hasil penilaian dalam bentuk transkrip nilai. Transkrip nilai merupakan gambaran umum kompetensi santri dalam setiap mata kuliah. Transkrip nilai diambil di idaroh pada biro dministrasi akademik. <b>Jika terjadi kesalahan nilai </b>pada transkrip nilai maka peserta menghubungi ustadz untuk perbaikan nilai; setelah perbaikan nilai maka peserta menginformasikan perbaikan nilai ke idaroh biro administrasi akademik untuk mendapatkan transkrip nilai yang baru.<br />	<br /><b>16. IJAZAH</b><br />Peserta yang membutuhkan Ijazah, dipersilakan mengisi link Data Ijazah Santri santri, lalu konfirmasi ke kontak admin untuk segera dibuatkan Ijazahnya.<br /><br /><b>17. LAIN-LAIN</b><br />Peserta/Santri Takhassus yang berkehendak menghadiahkan/menghibahkan barang berupa CD, buku bacaan, Al-Quran atau barang lainnya berupa media/sarana untuk berdakwah; maka Santri Takhassus tidak diperkenankan membagikan barang tersebut langsung kepada santri takhassus tapi hendaklah menyampaikan barang-barang tersebut terlebih dahulu ke pihak management takhassus untuk diproses dan mendapatkan izin.', 4, 1),
('panduan-ustadz', 'Panduan Ustadz', 'KIAS', 'Panduan Ustadz KIAS: rois qism, tugas ustadz, kegiatan mengajar, penamian, dan kehadiran.', '<b>1. PENDAHULUAN</b><br />Maha suci Allah yang telah menciptakan alam semesta dengan teratur.<br /><br />2.TUJUAN<br />Panduan ini dibuat dengan tujuan memudahkan para Ustadz dalam melaksanakan tugas di KIAS<br /><i> </i><br />3. PROGRAM KIAS<br />Program Pendidikan Tajwid al-Quran<br />1) Al-Barkah Tajwid al-Quran<br />Program Pendidikan Bahasa Arab<br />1) Al-Barkah BA Reguler<br />2) Al-Barkah BA Takmili<b><br /></b>4. TEMPAT BELAJAR DAN ALAMAT<br />Ma’had Syathiby<br />Jl Pahlawan Kampung Tengah Komplek Mesjid Al-Barkah &amp; Radio Rodja 756am Cileungsi Kab. Bogor 16820<br />Telp. 0811-1516-756<br /><br />5. INFORMASI<br />Yang berwenang menginformasikan tentang KIAS adalah mudir/management/admin KIAS<br /><br />6. ROIS QISM<br />Rois Qism adalah ustadz yang mendapat tugas tambahan berupa amanah sebagai rois qism.<br /><br />7. TUGAS ROIS QISM<br />a. Menyusun struktur kurikulum<br />b .Mendistribusikan pembagian tugas mengajar <br />c. Menyusun jadwal pelajaran<br />d. Menyusun jadwal raker<br />e. Menyusun panitia Penerimaan Santri Baru<br />f. Dll<br /><br />8. USTADZ<br />Ustadz adalah mereka yang mendapatkan amanah sebagai ustadz di KIAS.<br /><br />9. TUGAS USTADZ<br />Menyusun Adm Ustadz al.: <br />a. Menyusun silabus<br />b. Menyusun administrasi pembelajaran <br />c. Melaksanakan tugas mengajar<br />d. Melaksanakan tugas administrasi UTS dan UASe. Melaporkan Nilai UTS dan UAS<br />f. Melaksanakan tugas kepanitiaan<br />g. Dll.<br /><br />10. KEGIATAN MENGAJAR<br />Selama kegiatan mengajar ustadz melaksanakan tugas dengan sungguh-sungguh dan mengerjakan tugas-tugas di luar mengajar dengan penuh tanggung jawab<br /><br />12. PENAMPILAN<br />Ustadz berpenampilan sopan dan sesuai ketentuan syariat (dalam berpakaian dan bertutur kata)<br /><br />13. KEHADIRAN<br />Ustadz dapat menginformasikan izin tidak melaksanakan tugas via hp/telepon ke roisul qism. <br /><br />14. JAM MENGAJAR<br />Ustadz hadir sebelum jam pelajaran dimulai*)Jika terlambat masuk kelas, maka tidak menambah waktu, tetap berakhir sesuai batas jam pelajaran, sehingga tidak mengganggu jam berikutnya<br /><br />', 5, 1),
('info-psb-kias', 'Info PSB KIAS 2027/2028', 'KIAS', 'Informasi pendaftaran Santri Baru (PSB) KIAS 2027/2028: muqodimah, persyaratan, tes masuk, program, biaya, teknis pendaftaran, dan fasilitas.', '<b>INFO PSB KIAS 2027/2028 </b>🟨🟧🟩<u><b>MUQODIMAH</b></u><b>بسم الله الرحمن الرحيم</b><b><br /></b><b>السلام عليكم ورحمة الله وبركاته</b><br /><b>Selamat datang </b>Calon Peserta KIASdi Link Informasi Pendaftaran Santri Baru (PSB) 2027/2028<b>بارك الله فيكم</b><b>-------------------------------------</b><b><br /></b><b>Mengapa memilih KIAS? </b>Karena Lembaga ini memiliki keunikan dan berbeda dengan lembaga pendidikan yang telah ada; lembaga ini mengembangkan kurikulum yang berpusat pada potensi, perkembangan dan kepentingan para santri dan lingkungannya; beragam dan terpadu, relevan dengan kebutuhan kehidupan; menyeluruh dan berkesinambungan serta belajar sepanjang hayat.<br /><b>In Syaa Allah</b> para peserta akan mendapatkan pendidikan yang bermutu, dinamis dan menyenangkan; bersifat tashfiyah dan tarbiyah; suasana yang saling menerima, menghargai akrab sesuai sunnah; seimbang terkait dan berkesinambungan antar jenjang pendidikan.<br /><b>Kesimpulannya adalah</b> marilah mempelajari ilmu syari dengan bergabung bersama KIAS<br /><b>-------------------------------------</b><br /><b>KONTAK ADMIN WINDY ASKOT</b>0811-1516-756<b><u>PERSYARATAN</u></b><b>=Persyaratan Umum:</b>1. Muslim/Muslimah<b>2. Mengisi Formulir Pendaftaran baik daftar Online ataupun Offline</b>3. Copy Identitas/KTP/KK/Kartu Pelajar<b>4. Pas Foto 4x6 1 lembar</b>5. Mengikuti Tes Tulis dan Wawancara<b>-------------------------------------</b><b><br /></b><b>=Persyaratan Khusus:</b><b>Persyaratan Program Tajwid</b>- Belajar Tajwid Al-Quran<b>Persyaratan Program Bahasa Arab</b>- Mampu Baca Tulis Al-Quran<b>-------------------------------------</b><br /><b>KONTAK ADMIN WINDY ASKOT</b>0811-1516-756<b><u>TES MASUK</u></b><b>Tes Masuk KIAS SYATHIBY</b>Hari           : Sabtu, 21 Agustus 2027<b>Pukul        : 08.00-12.00</b>Tempat      : Ma''had Tahfidz Imam Syathiby Kampung Tengah Rt 1/5 Cileungsi <b>Kec. Cileungsi Kab. Bogor 16820</b><b>Awal kuliah:  Sabtu, 4 September 2027<br /></b><b>-------------------------------------</b><br /><b>KONTAK ADMIN WINDY ASKOT</b>0811-1516-756<br /><b><u>PROGRAM DAN PILIHAN WAKTU </u></b><b>(1) Tajwid Al-Quran</b><b>Al-Barkah Tajwid Al-Quran (1 Tahun)</b>Tempat Kuliah Ma''had SyathibyHari Sabtu (07.30-11.40)<b>-------------------------------------</b><b>(2) Bahasa Arab</b><b>Al-Barkah BA Reguler (2 Tahun)</b>Tempat Kuliah Ma''had SyathibyHari Sabtu (07.30-11.40)<b>Al-Barkah BA Takmili (1 Tahun)</b><br />Tempat Kuliah Ma''had SyathibyHari Sabtu (07.30-11.40)<b>-------------------------------------</b><b>KONTAK ADMIN WINDY ASKOT</b><br />0811-1516-756<b>BIAYA PENDIDIKAN</b><b>Pendaftaran</b> Rp 150.000,- per program<b>-------------------------------------</b><b>Sarpras</b> Rp 300.000,- per program<b>-------------------------------------</b><b>SPP/Syahriyyah</b> Rp 250.000.- per bulan<br /><b>-------------------------------------</b><br /><b>KONTAK ADMIN WINDY ASKOT</b><br />0811-1516-756<br />0812-2275-6756<b><u>TEKNIS PENDAFTARAN</u></b><b>Pendafaran KIAS</b><b>Waktu Pendaftaran:</b>Mei-18 Agustus 2027Silakan kontak Admin terlebih dahulu<br /><b>Akhir Pendaftaran</b><br />Rabu, 18 Agustus 2027<b>Tempat    </b>:<b> </b>Ma''had Tahfidz Imam Syathiby Kampung Tengah Rt 1/5 Cileungsi <b>Kec. Cileungsi Kab. Bogor 16820</b><b>PENDAFTARAN VIA ONLINE</b><b>KLIK LINK BERIKUT</b><b>-------------------------------------</b><br /><b>KONTAK ADMIN WINDY ASKOT</b>0811-1516-756<b><u>FASILITAS</u></b><b>Fasilitas </b><br /><b>Masjid Al-Barkah</b>Musholla Ma''had Syathiby<b>Perpustakaan Ma''had Syathiby</b>Ruang Kelas Ber-AC<b>Ruang Parkir Luas</b><b>-------------------------------------</b><b><br /></b><b>KONTAK ADMIN WINDY ASKOT</b>0811-1516-756<b><u>INFO PENGAJAR</u></b><b>-------------------------------------</b><br /><b>Nama Pengajar:</b><b>01. Ust. Badru Salam, Lc.</b>02. Ust.  Dr. Muhammad Yasir, M.A.<b>03. Ust. Dr. Cecep Rahmat, Lc. M.Ag.</b>04. Ust. Cecep Nurohman, B.A., M.A.<br /><b>05. Ust. Zahirman Edri</b>06. Ust. Irham Maulana, B.A., M.H.<b>07. Ust. Derma Permana, B.A.</b><br />08. Ust. Jufri, B.A.<br /><b>09. Ust. Andi Setio, S.Pd.I.</b>10. Ust. Muhammad Irfandi, B.A.,M.A.<b>11. Ust. Azhar Hajid</b>12. Ust. Muhammad Alan, B.A.<br /><b>13. Ust. Rahmat H. Bachtiar, B.A., M.Pd.<br /></b>14. Ust. Adnan Maulana<b>15. Ust. Rifki</b>16. Ust. Yusuf<b>17. Usth. Ummu Rifáh, B.A.</b>18. Usth. Rifáh<b>Dan pengajar lain yang kompeten</b><br /><b>-------------------------------------</b><br /><b>KONTAK ADMIN WINDY ASKOT</b>0811-1516-756<b><u>MUQORROR</u></b><b>PROGRAM TAJWID</b>1) Metode As-Syafi''i (Ust. Kurnaedi, Lc.)2) Qiroah wal Kitabah Silsilah Jilid 1 (Jami''ah Muhammad Bin Su''ud KSA)<b>-------------------------------------</b><b><br /></b><b>PROGRAM BAHASA ARAB </b><b> </b><b>REGULER </b><b>1</b>1) Muqodimah Mukhtarot (Ust. Zahir Al-Minangkabawi)2) Auzan Mukhtarot (Ust. Zahir Al-Minangkabawi)3) Mukhtarot Qowaid Al-Lughah Al-Arabiyah (Ust. Aunur Rofiq bin Gufron, Lc.)4) Tadribat Mukhtarat Durusul Lughah (Ust. Abu Izza Irham Maulana, Lc.)5) Durusul Lughah Jilid 1 (Syaikh Dr. V. Abdurrahim)6) Al-Lamhah Fi Tashrif wa Qowaidihi (Ust. Zahir Al-Minangkabawi)<b>-------------------------------------</b><br /><b>PROGRAM BAHASA ARAB </b><b>REGULER </b><b>2</b>1) Mukhtarot Qowaid Al-Lughah Al-Arabiyah (Ust. Aunur Rofiq bin Gufron, Lc.)<br />2) Tadribat Mukhtarat Durusul Lughah (Ust. Abu Izza Irham Maulana, Lc.)3) Durusul Lughah Jilid 2 (Syaikh Dr. V. Abdurrahim)4) Al-Lamhah Fi Tashrif wa Qowaidihi (Ust. Zahir Al-Minagkabawi)<b>-------------------------------------</b><b><br /></b><b>PROGRAM TAKMILI</b>1) Matan Ushul Tsalatsah (Syaikh Muhammad bin Abdul Wahab)2) Matan Ushul Shittah (Syaikh Muhammad bin Abdul Wahab)3) Matan Al-Qowaidul Arbaa (Syaikh Muhammad bin Abdul Wahab)4) Fadhlu Al-Islam (Syaikh Muhammad bin Abdul Wahab)5) Syarah Arbain Nawawi (Imam Ibnu Daqiq Al-Id)6) Tadrib Al-Qiroah (Ust. Zahir Al-Minangkabawi)7) Durusul Lughah Jilid 3 (Syaikh Dr. V. Abdurrahim)<b>-------------------------------------</b><b>KONTAK ADMIN WINDY ASKOT</b>0811-1516-756<b>PENUTUP</b><b>الحمد لله saya sudah mengisi semua data dengan benar.</b><br />dan saya sudah membayar biaya pendaftaran Rp 250.000,- ke Admin.<br /><b>-------------------------------------</b><br /><b>Kami Admin KIAS mengucapkan</b><br /><b>شكرا وجزاكم الله خيرا</b> atas pendaftaran Offline atau Online-nya<b>KONTAK ADMIN WINDY ASKOT</b>0811-1516-756', 6, 1);
